import { notFound, redirect } from "next/navigation"
import fs from "node:fs"
import path from "node:path"
import { auth } from "@/lib/auth"
import { isAdmin } from "@/lib/admin"
import { ProfileScanFromData, type ProfileScanRaw } from "@/document/screens/ProfileScan"
import ReportActions from "../../recoil/[reportId]/ReportActions"

// Dynamic Profile Scan — renders a scan generated by the profile-scan pipeline
// (see _SPECS/profile-scan-spec-v1.md). Scans are written to
// runtime/scan/generated/<scanId>.json, committed alongside the page, then
// this route renders them through the same canonical document kit as the
// static ZACH_PROFILE sample at the ProfileScan screen.
export const dynamic = "force-dynamic"

function loadScan(scanId: string): ProfileScanRaw | null {
  const safe = scanId.replace(/[^a-zA-Z0-9_-]/g, "")
  const file = path.join(process.cwd(), "runtime", "scan", "generated", `${safe}.json`)
  if (!fs.existsSync(file)) return null
  try {
    return JSON.parse(fs.readFileSync(file, "utf-8")) as ProfileScanRaw
  } catch {
    return null
  }
}

export default async function DynamicProfileScanPage({
  params,
}: {
  params: Promise<{ scanId: string }>
}) {
  // ADR-001 doctrine: prod enforces session, dev passes through (matches the
  // soft-auth pattern on all /api routes and the /recoil route; also enables
  // local visual QA of generated scans without a magic-link session).
  if (process.env.NODE_ENV !== "development") {   // fail-closed: unset/test/preview/staging all gate (matches /recoil, /warroom)
    const session = await auth()
    if (!session?.user?.email) redirect("/compass?next=/scan/" + (await params).scanId)
    if (!isAdmin(session)) notFound()
  }

  const { scanId } = await params
  const data = loadScan(scanId)
  if (!data) notFound()

  return (
    <div style={{ background: "#020408", minHeight: "100vh", padding: "40px 0" }}>
      {/* Print layer: the screen keeps the dark reader cockpit; print flattens to a
          light framed sheet (the established ARCS print grammar — see the resume
          family in _ARTIFACTS). Global app chrome (EyebrowToast, StickyFooter) is
          suppressed for print only; nothing outside this route is modified. */}
      <style>{`
        @page { size: letter; margin: 0.45in; }
        @media print {
          /* body's own dark background (globals.css) is not covered by the
             visibility rule below — force the sheet white. */
          html, body { background: #ffffff !important; }
          /* Only the document prints; app chrome (toast/footer/actions) does not. */
          body * { visibility: hidden; }
          #scan-doc, #scan-doc * { visibility: visible; }
          #scan-doc { position: absolute; left: 0; top: 0; width: 100%; }
          /* Flatten the dark cockpit to a light sheet: invert luminance, keep hue.
             The kit's accents (red/gold/green/orange threads) survive with their
             semantic identity; ink-heavy full-bleed dark becomes print-safe. */
          /* NOTE: filter inverts the element INCLUDING its own background — so give
             it the dark bg and let inversion produce the light sheet. */
          #scan-doc { filter: invert(0.94) hue-rotate(180deg); background: #020408 !important; }
          #scan-doc img { filter: invert(1) hue-rotate(180deg); }
          /* Per-page frame — repeats on every sheet (position:fixed at print). */
          #scan-frame { display: block !important; visibility: visible; position: fixed; inset: 0; border: 1.4px solid #c2ccd6; border-radius: 7px; pointer-events: none; }
          * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        }
      `}</style>
      <div id="scan-frame" style={{ display: "none" }} />
      <div style={{ maxWidth: 760, margin: "0 auto", padding: "0 20px" }}>
        <ReportActions />
        <div id="scan-doc">
          <ProfileScanFromData data={data} />
        </div>
      </div>
    </div>
  )
}
